<?php require_once 'config/database.php'; require_once 'includes/auth.php';require_once 'includes/ui.php'; requireLogin();
$id=(int)$_SESSION['user_id'];$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$status=trim($_POST['student_status']??'');$semester=(int)($_POST['semester']??0);$fakultas=trim($_POST['fakultas']??'');$hp=trim($_POST['nomor_hp']??'');if($status===''||$semester<1||$semester>14||$fakultas===''||$hp==='')$err='Semua data profil wajib diisi.';else{$st=$conn->prepare('UPDATE users SET student_status=?,semester=?,fakultas=?,nomor_hp=?,profile_completed=1 WHERE id=?');$st->bind_param('sissi',$status,$semester,$fakultas,$hp,$id);if($st->execute()){$msg='Profil berhasil disimpan.';$_SESSION['profile_completed']=1;}else$err='Profil gagal disimpan.';$st->close();}}
$st=$conn->prepare('SELECT name,email,student_status,semester,fakultas,nomor_hp,profile_completed FROM users WHERE id=?');$st->bind_param('i',$id);$st->execute();$u=$st->get_result()->fetch_assoc();$st->close();
if(isAdmin()){ $titleForTop='Profil Admin'; } else {$titleForTop='Profil Saya';}
renderHead('Profil Saya'); if(isAdmin())renderAdminNav('profile'); else renderUserNav('profile'); ?>
<div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Profil Saya</h1><p class="muted">Data ini akan digunakan saat kamu membuat laporan dan proses verifikasi.</p></div></div><?php if(isset($_GET['required'])): ?><div class="notice notice-warn">Lengkapi profil terlebih dahulu sebelum menggunakan fitur laporan.</div><?php endif; ?><?php if($msg): ?><div class="notice notice-ok"><?= e($msg) ?></div><?php endif; ?><?php if($err): ?><div class="notice notice-error"><?= e($err) ?></div><?php endif; ?><div class="card form-card"><div class="form-row"><div class="form-group"><label>Nama Lengkap</label><input class="form-control" value="<?= e($u['name']) ?>" disabled></div><div class="form-group"><label>Email</label><input class="form-control" value="<?= e($u['email']) ?>" disabled></div></div><form method="post"><div class="form-row"><div class="form-group"><label>Status</label><select class="form-select" name="student_status" required><option value="">Pilih status</option><?php foreach(['Mahasiswa','Dosen','Staff','Alumni'] as $x): ?><option <?= $u['student_status']===$x?'selected':'' ?>><?= e($x) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Semester</label><input class="form-control" type="number" min="1" max="14" name="semester" value="<?= e($u['semester']) ?>" required></div></div><div class="form-row"><div class="form-group"><label>Fakultas</label><input class="form-control" name="fakultas" value="<?= e($u['fakultas']) ?>" placeholder="Contoh: FMIPA" required></div><div class="form-group"><label>Nomor HP</label><input class="form-control" name="nomor_hp" value="<?= e($u['nomor_hp']) ?>" required></div></div><button class="btn btn-primary" type="submit">Simpan Profil</button></form></div></div><?php renderFooter(); ?>
